# Inputs are constructed within the stated limits and preserve problem-specific invariants.
import random


def generate(seed: int = 0) -> list[str]:
    r = random.Random(seed)
    vals = set()
    for _ in range(600):
        n = r.randint(1, 12)
        d = tuple(r.randint(1, 100000) for _ in range(n))
        h = round(r.uniform(1, 30), 2)
        vals.add((d, h))
    calls = [f"candidate(dist={list(a)!r}, hour={b!r})" for a, b in vals]
